-- ADCT, comentários didáticos, lote 15 (arts. 135 a 138), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Créditos remanescentes dos tributos federais extintos$c$, aplicacao_pratica = $a$Remete à lei complementar a forma de uso dos créditos, inclusive presumidos, do imposto do art. 153, IV, das contribuições do art. 195, I, "b", e IV, e da contribuição para o Programa de Integração Social do art. 239, não apropriados ou não utilizados até a extinção desses tributos. Só para os créditos que cumpram os requisitos da legislação vigente na data da extinção, mantém a compensação com outros tributos federais, inclusive a contribuição do art. 195, V, ou o ressarcimento em dinheiro.$a$ where codigo='adct' and numero=135 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Contribuições estaduais para fundos de infraestrutura e habitação$c$, aplicacao_pratica = $a$Permite aos Estados que, em 30 de abril de 2023, tinham fundos de investimento em infraestrutura e habitação financiados por contribuições sobre produtos primários e semielaborados, exigidas como condição de diferimento, regime especial ou outro tratamento diferenciado do imposto do art. 155, II, instituir contribuições semelhantes não vinculadas a esse imposto, sem alíquota ou base superiores às vigentes naquela data (I), com extinção da contribuição vinculada correspondente (II), com a mesma destinação de receita (III) e com extinção em 31 de dezembro de 2043 (IV). O parágrafo único exclui essas receitas do cálculo dos arts. 130, II, "b", e 131, § 2º, I, "b", do ADCT.$a$ where codigo='adct' and numero=136 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Saldos dos repasses da Covid-19 até 2024$c$, aplicacao_pratica = $a$Permitiu aplicar, até 31 de dezembro de 2024, os saldos dos recursos transferidos de 2020 a 2022 pelo Fundo Nacional de Saúde e pelo Fundo Nacional de Assistência Social aos fundos estaduais, municipais e distritais para enfrentamento da pandemia de Covid-19, no custeio de ações e serviços públicos de saúde e de assistência social, observadas as diretrizes do Sistema Único de Saúde e do Sistema Único de Assistência Social. Norma de prazo já encerrado.$a$ where codigo='adct' and numero=137 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Limite ao crescimento de despesas vinculadas até 2032$c$, aplicacao_pratica = $a$Até 2032, impede que a criação, alteração ou prorrogação de vinculação legal ou constitucional de receitas a despesas, inclusive de aplicação mínima de recursos, gere crescimento anual da despesa primária correspondente acima da variação do limite de despesas primárias, na forma da lei complementar do art. 6º da Emenda Constitucional nº 126/2022.$a$ where codigo='adct' and numero=138 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
